export function decode(hrp, address) {
  const [decodedHrp, data] = decodePayload(address);
  if (decodedHrp === null || decodedHrp !== hrp) {
    return [null, null];
  }

  const witnessVersion = data[0];
  const witnessProgram = convertBits(data.slice(1), 5, 8, false);

  if (witnessProgram === null) {
    return [null, null];
